  root.appendChild(hdr);

  var body = _el("div", "padding:16px 18px 18px;");
  root.appendChild(body);

  var all = opts.items || [];
  var lead = _el("div", "font:600 11.5px/1.5 " + UI + ";color:#334155;margin-bottom:11px;");
  lead.appendChild(_el("b", "color:#0f172a;", "You'll review each one in turn."));
  lead.appendChild(document.createTextNode("  Insert or skip, in document order."));
  body.appendChild(lead);

  var listBox = _el("div", "background:#fff;border:1px solid #e4e8ee;border-radius:3px;" +
    "box-shadow:0 1px 2px rgba(15,23,42,.04);margin-bottom:12px;");
  // Every selected paragraph is listed, in document order. Clean ones are
  // muted rather than hidden, so the scan is auditable — you can see what it
