  body.appendChild(go);

  return { root: root };
}

view.renderPolishWorkspace:
function renderPolishWorkspace(opts) {
  opts = opts || {};
  var host = opts.host;
  if (!host) return null;

  var UI = "Inter,'Segoe UI',system-ui,sans-serif";
  var GOLD = "#c9a227";
  // Neutral buttons use the platinum gradient (project convention); the
  // single primary action is the only saturated control on the surface.
  var PLATINUM = "font:700 9.5px/1 " + UI + ";letter-spacing:.06em;text-transform:uppercase;" +
    "padding:7px 11px;color:#3b4757;background:linear-gradient(180deg,#ffffff,#e9edf2);" +
    "border:1px solid #c3ccd6;border-radius:2px;cursor:pointer;" +
    "box-shadow:inset 0 1px 0 #fff,0 1px 1.5px rgba(15,23,42,.07);";
  var PRIMARY = "font:800 10px/1 " + UI + ";letter-spacing:.09em;text-transform:uppercase;" +
    "padding:9px 17px;color:#fff;background:linear-gradient(180deg,#1a8a5c,#116844);" +
    "border:1px solid #0d4f34;border-radius:2px;cursor:pointer;" +
    "box-shadow:inset 0 1px 0 rgba(255,255,255,.20),0 1px 3px rgba(15,23,42,.20);";
  var CARD = "background:#fff;border:1px solid #e4e8ee;border-radius:3px;margin-bottom:14px;" +
    "box-shadow:0 1px 2px rgba(15,23,42,.04),0 10px 24px rgba(15,23,42,.055);overflow:hidden;";
  var PROSE = "font:400 15px/1.72 Georgia,'Times New Roman',serif;color:#111827;" +
    "padding:11px 14px;margin:2px 13px 0;border:1px solid transparent;border-radius:2px;" +
    "outline:none;white-space:pre-wrap;";
  var LAB = "font:800 9px/1 " + UI + ";text-transform:uppercase;letter-spacing:.16em;color:#0f172a;";
  var WHY = "font:400 11px/1.4 " + UI + ";color:#7b8494;";
  var PILL = "font:700 9.5px/1 " + UI + ";color:#64748b;background:#f4f6f9;" +
    "border:1px solid #e4e8ee;border-radius:10px;padding:4px 9px;margin-left:auto;white-space:nowrap;";
  // Each version gets its own identity so the three are distinguishable at a
  // glance rather than reading as three identical white boxes.
  var ACCENTS = [
    { key: "gold",   edge: "#c9a227", lite: "#e2c257", tint: "#fffdf5", ink: "#7a5c07", soft: "#efe2b6" },
    { key: "teal",   edge: "#0f766e", lite: "#199c92", tint: "#f2fbfa", ink: "#0b5e57", soft: "#bfe3df" },
    { key: "indigo", edge: "#4f46e5", lite: "#6f68ea", tint: "#f6f5ff", ink: "#3b35b8", soft: "#cfccf5" },
  ];
  // Dark floating toolbar shown over a highlight inside a version.
  var DARKBTN = "font:700 9px/1 " + UI + ";letter-spacing:.06em;text-transform:uppercase;" +
    "padding:6px 9px;color:#e8edf4;background:#1f2a3a;border:1px solid #33425a;" +
    "border-radius:2px;cursor:pointer;white-space:nowrap;";

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;")
      .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }
  function _el(tag, css, text) {
    var e = document.createElement(tag);
    if (css) e.style.cssText = css;
    if (text != null) e.textContent = text;
    return e;
  }
  function _btn(css, label, cls) {
    var b = _el("button", css, label);
    b.type = "button";
    if (cls) b.className = cls;
    return b;
  }
  // Word-level LCS diff — a rewrite needs real alignment; prefix/suffix
  // diffing would just strike the whole passage and re-add it.
  function _diffHtml(oldS, newS) {
    var A = String(oldS).match(/\S+|\s+/g) || [];
    var B = String(newS).match(/\S+|\s+/g) || [];
    var n = A.length, m = B.length;
    if (n * m > 400000) return _esc(newS);
    var dp = [], i, j;
    for (i = 0; i <= n; i++) { dp.push(new Array(m + 1).fill(0)); }
    for (i = n - 1; i >= 0; i--) {
      for (j = m - 1; j >= 0; j--) {
        dp[i][j] = (A[i] === B[j]) ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
      }
    }
    var out = ""; i = 0; j = 0;
    while (i < n && j < m) {
      if (A[i] === B[j]) { out += _esc(A[i]); i++; j++; }
      else if (dp[i + 1][j] >= dp[i][j + 1]) { out += '<span class="_pl_del">' + _esc(A[i]) + "</span>"; i++; }
      else { out += '<span class="_pl_add">' + _esc(B[j]) + "</span>"; j++; }
    }
    while (i < n) { out += '<span class="_pl_del">' + _esc(A[i++]) + "</span>"; }
    while (j < m) { out += '<span class="_pl_add">' + _esc(B[j++]) + "</span>"; }
    return out;
  }

  // NOT innerHTML = "" — claimOutput() intentionally keeps (and hides)
  // #_eli3_dashboard_root because other v3 tools, Ask ELI included, mount
  // into it. Wiping it leaves their next open with a null mount.
  Array.prototype.slice.call(host.children).forEach(function (c) {
    if (c && c.id !== "_eli3_dashboard_root") host.removeChild(c);
  });
  var root = _el("div", "background:#f7f8fa;border:1px solid #e4e8ee;font-family:" + UI + ";");
  root.className = "_pl_root";
