jsonTools.init:
function init(eli) {
  // Per-card regen steering. The card's popover passes what the user typed;
  // it rides on the same instruction the register was generated from, so the
  // steer refines rather than replaces the original intent.
  // Nested, not column-0: build_tool.js splits at top-level `function NAME(`.
  function _steered(base, steer) {
    var b = String(base == null ? "" : base).trim();
    var s = String(steer == null ? "" : steer).trim();
    if (!s) return base;
    return b ? (b.replace(/\s*$/, "") + " " + s) : s;
