  // window (kernel evalBundle: "Stored on bundle for kernel dispatch; not
  // attached to window"). Resolve them here or every call is a ReferenceError.
  var bundle = eli.tools && eli.tools._loaded && eli.tools._loaded["polish"];
  if (!bundle) return;
  var polishAnalyze = bundle._eliEngineFns && bundle._eliEngineFns.polishAnalyze;
  var polishFragment = bundle._eliEngineFns && bundle._eliEngineFns.polishFragment;
  var renderPolishWorkspace = bundle._eliViewFns && bundle._eliViewFns.renderPolishWorkspace;
  var renderPolishBatchStart = bundle._eliViewFns && bundle._eliViewFns.renderPolishBatchStart;
  if (!polishAnalyze || !renderPolishWorkspace) {
    if (eli.log && typeof eli.log.event === "function") {
      eli.log.event("tool", "polish_init_missing_fns", {
        engine: !!polishAnalyze, view: !!renderPolishWorkspace,
      });
    }
    return;
  }

  var _busy = false;

  // Capture the selection AND bookmark it, so the insert still lands after
  // the user has clicked around the taskpane and lost the live selection.
  // ─── [FMT] ───────────────────────────────────────────────────────────
  // Per-run bold/italic/underline out of the selection's OOXML. Range.font
  // returns null across mixed runs and Office.js has no run enumeration,
  // so the XML is the only way to see where emphasis actually sits.
  function _parseRuns(ooxml) {
    var out = [];
    try {
      var doc = new DOMParser().parseFromString(String(ooxml || ""), "application/xml");
      var rs = doc.getElementsByTagName("w:r");
      for (var i = 0; i < rs.length; i++) {
        var r = rs[i];
        var ts = r.getElementsByTagName("w:t");
