  // A clause opening with a bold or underlined run that ends in "." or ":"
  // is a HEADING, not prose — "Indemnification." The AI shouldn't rewrite
  // it, and its formatting is exact rather than inferred, so it's held back
  // from the rewrite and re-attached verbatim on insert.
  function _leadHeading(runs) {
    if (!runs || !runs.length) return null;
    var i = 0, pre = "";
    // A non-bold section number usually precedes the heading — "5.1  ".
    // It isn't part of the heading's formatting, so it's carried as its
    // own unformatted piece rather than being swept into the bold run.
    while (i < runs.length && !runs[i].bold && !runs[i].underline &&
           /^[\s\d.()]+$/.test(runs[i].text) && pre.length < 16) {
      pre += runs[i].text; i++;
