  // ─── [/FMT] ──────────────────────────────────────────────────────────

  // ─── [SRC-MARK] ──────────────────────────────────────────────────────
  // Highlight the passage being worked on so you can see it in Word while
  // the workspace is open — the selection itself is lost the moment focus
  // moves to the taskpane, so a selection won't do.
  //
  // Tracking is forced Off and restored inside the run: a highlight is a
  // formatting revision and this tool's whole point is a clean insert.
  // Cleared on insert, skip and back; also cleared before painting a new
  // one so a stray can't accumulate.
  var SRC_MARK_COLOR = "#FFF2A8";
  var _srcMarked = null;
  function _markSource(bookmark, on) {
