  }
  // ─── [/SRC-MARK] ─────────────────────────────────────────────────────

  function _readSelection() {
    return eli.host.runRaw("polish:read-selection", async function (context) {
      var sel = context.document.getSelection();
      sel.load("text");
      var paras = sel.paragraphs;
      paras.load("items");
      var ooxml = sel.getOoxml();                       // [FMT]
      await context.sync();
      var text = String(sel.text || "");
