      // struck-through deletions ("the cust customer omer shall"). Polishing
      // that means rewriting garbage — use the POST-ACCEPT text instead.
      var hadRedlines = false;
      try {
        var helpers = eli.host && eli.host.helpers;
        if (helpers && typeof helpers.readResolvedText === "function") {
          var info = await helpers.readResolvedText(sel);
          if (info && info.hasRedlines && info.resolvedText) {
            text = String(info.resolvedText);
            hadRedlines = true;
          }
        }
      } catch (e) { /* fall back to the raw selection text */ }

